import { pinyin } from "pinyin-pro";

export function normalizeSearch(value: string) {
  return value.toLowerCase().normalize("NFKD").replace(/[\s_./:()[\]{}'"-]+/g, "");
}

function pinyinForms(value: string) {
  const syllables = pinyin(value, { toneType: "none", type: "array" });
  return [syllables.join(""), syllables.map((item) => item[0] ?? "").join("")];
}

function subsequenceScore(haystack: string, needle: string) {
  if (haystack.length > Math.max(48, needle.length * 6)) return Number.POSITIVE_INFINITY;
  let cursor = 0;
  let gap = 0;
  for (const character of needle) {
    const found = haystack.indexOf(character, cursor);
    if (found < 0) return Number.POSITIVE_INFINITY;
    gap += found - cursor;
    cursor = found + 1;
  }
  return 72 + gap + Math.max(0, haystack.length - needle.length) * 0.12;
}

export function fuzzySearchScore(value: string, query: string) {
  const needle = normalizeSearch(query);
  if (!needle) return 0;
  const forms = [normalizeSearch(value), ...pinyinForms(value).map(normalizeSearch)];
  let best = Number.POSITIVE_INFINITY;
  forms.forEach((form, index) => {
    const direct = form.indexOf(needle);
    if (direct >= 0) best = Math.min(best, direct + index * 8 + Math.max(0, form.length - needle.length) * 0.02);
    best = Math.min(best, subsequenceScore(form, needle) + index * 8);
  });
  return best;
}

export function matchesSearch(value: string, query: string) {
  return Number.isFinite(fuzzySearchScore(value, query));
}
